                        this.child(
                            div()
                                .id(format!("{id_prefix}waiting-indicator-{ix}"))
                                .child(
                                    Icon::new(IconName::Warning)
                                        .size(IconSize::XSmall)
                                        .color(Color::Warning),
                                )
                                .tooltip(Tooltip::text(tooltip_text)),
                        )
                    })
                    .when(
